def count_substrings(s):
    def pal(i, j):             # is s[i..j] a palindrome?
        if i >= j:
            return True
        return s[i] == s[j] and pal(i + 1, j - 1)

    n = len(s)
    return sum(pal(i, j) for i in range(n) for j in range(i, n))

